package com.personal.assistant.module.scheduler.job;import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.personal.assistant.module.backup.entity.BackupRecord;import com.personal.assistant.module.backup.service.BackupService;import org.springframework.stereotype.Component;
@Component public class DataBackupHandler implements JobHandler{private final BackupService service;private final ObjectMapper json;public DataBackupHandler(BackupService service,ObjectMapper json){this.service=service;this.json=json;}public String type(){return "DATA_BACKUP";}public String execute(String config){try{JsonNode node=json.readTree(config==null?"{}":config);if(!node.hasNonNull("userId"))throw new IllegalArgumentException("备份调度配置必须包含 userId");BackupRecord r=service.runFullBackup(node.get("userId").asLong());return "备份完成: "+r.getFilePath();}catch(Exception e){throw new IllegalArgumentException(e.getMessage(),e);}}}
